from .api.soap import AlarmDelegateService, Response


class FmSoapApi:
    def __init__(self, web_url, username, password):
        self.web_url = web_url
        self.username = username
        self.password = password
        self._alarm_delegate_service = None

    @property
    def alarm_delegate_service(self):
        if not self._alarm_delegate_service:
            self._alarm_delegate_service = AlarmDelegateService(
                self.web_url, self.username, self.password)
        return self._alarm_delegate_service

    def acknowledge_alarms(self, alarm_ids, ack_time=None, ignore_failure=False):
        """
        Acknowledge alarm(s) for given alarm id(s) and
        return the alarm id(s) for which the acknowledge operation failed.

        Example output::

            [{
                'alarmKey': {
                    'alarmId': 911200
                },
                'exception': 'The alarm is already in Acknowledged state',
                'success': False
            },
            {
                'alarmKey': {
                    'alarmId': 911201
                },
                'exception': 'Alarm either does not exist or is already in cleared and acknowledged state.',
                'success': False
            }]

        :param int|list alarm_ids: Alarm id(s) to be acknowledged.
        :param datetime ack_time: UTC time when the alarm is acknowledged.
            If `None` then the time when alarm is acknowledged in NetAct system is used.
        :param bool ignore_failure: If True, returns the alarm id(s) for which the acknowledge operation failed.
            Otherwise raises OperationFailed exception.
        :return: Alarm id(s) for which the acknowledge operation failed.
        :rtype: list(dict)
        """
        alarm_keys = self._prepare_alarm_keys(alarm_ids)
        response = self.alarm_delegate_service.acknowledge_alarms_by_keys(
            alarm_keys=alarm_keys, ack_user_id=self.username, ack_time=ack_time)
        return Response(response, ignore_failure).verify

    def unacknowledge_alarms(self, alarm_ids, unack_time=None, ignore_failure=False):
        """
        Unacknowledge alarm(s) for given alarm id(s) and
        return the alarm id(s) for which the acknowledge operation failed.

        Example output::

            [{
                'alarmKey': {
                    'alarmId': 911200
                },
                'exception': 'The alarm is already in Acknowledged state',
                'success': False
            },
            {
                'alarmKey': {
                    'alarmId': 911201
                },
                'exception': 'Alarm either does not exist or is already in cleared and acknowledged state.',
                'success': False
            }]

        :param int|list alarm_ids: Alarm id(s) to be unacknowledged.
        :param datetime unack_time: UTC time when the alarm is unacknowledged.
            If `None` then the time when alarm is unacknowledged in NetAct system is used.
        :param bool ignore_failure: If True, returns the alarm id(s) for which the unacknowledge operation failed.
            Otherwise raises OperationFailed exception.
        :return: Alarm id(s) for which the acknowledge operation failed.
        :rtype: list(dict)
        """
        alarm_keys = self._prepare_alarm_keys(alarm_ids)
        response = self.alarm_delegate_service.unacknowledge_alarms_by_keys(
            alarm_keys=alarm_keys, unack_user_id=self.username, unack_time=unack_time)
        return Response(response, ignore_failure).verify

    def clear_alarms(self, alarm_ids, clear_time=None, ignore_failure=False):
        """
        Clear alarm(s) for given alarm id(s) and
        return the alarm id(s) for which the clear operation failed.

        Example output::

            [{
                'alarmKey': {
                    'alarmId': 911200
                },
                'exception': 'The alarm is already Cleared',
                'success': False
            },
            {
                'alarmKey': {
                    'alarmId': 911201
                },
                'exception': 'Alarm either does not exist or is already in cleared and acknowledged state.',
                'success': False
            }]

        :param int|list alarm_ids: Alarm id(s) to be cleared.
        :param datetime clear_time: UTC time when the alarm is cleared.
            If `None` then the time when alarm is cleared in NetAct system is used.
        :param bool ignore_failure: If True, returns the alarm id(s) for which the clear operation failed.
            Otherwise raises OperationFailed exception.
        :return: Alarm id(s) for which the clear operation failed.
        :rtype: list(dict)
        """
        alarm_keys = self._prepare_alarm_keys(alarm_ids)
        response = self.alarm_delegate_service.clear_alarms_by_keys(
            alarm_keys=alarm_keys, clear_user_id=self.username, clear_time=clear_time)
        return Response(response, ignore_failure).verify

    def _prepare_alarm_keys(self, alarm_ids):
        """
        Prepare alarmKeys.

        Example output::

            [
                {
                    'alarmId': 911200
                },
                {
                    'alarmId': 911201
                },
            ]


        :param int|list alarm_ids: Alarm id(s)
        :return: alarmKeys
        :rtype: list(dict)
        """
        alarm_ids = alarm_ids if isinstance(alarm_ids, list) else [alarm_ids]
        return [self.alarm_delegate_service.nsn_alarm_key(alarm_id=int(alarm_id)) for alarm_id in alarm_ids]
